import lxml.etree as ET
from dateutil.parser import parse
from .pm_log_entry import PMLogEntry
from .pm_setup import PMSetup
from taf.analyzer.base import LogsReader


class PMCounterLogReader(LogsReader):
    def __init__(self, interval=None, **kwargs):
        super(PMCounterLogReader, self).__init__(**kwargs)
        self.__pm_log_entries = {}
        self._interval = interval

    @classmethod
    def from_dir(cls, dir_path, file_pattern="*_PM_*", interval=None):
        """
        :param str dir_path: directory containing PM counter files
        :param str file_pattern: PM counter file name pattern ; default : "*_PM_*"
        :param list[int] interval: list of allowed intervals values
        :return: PMCounterLogReader object
        """
        return super(PMCounterLogReader, cls).from_dir(
            dir_path, file_pattern, interval=interval)

    def _parse_pm_file(self, file_object):
        """
        Parse a PM file.

        Convert the PMSetup XML elements from the PM file to a transformed PMSetup XML element.
        Add each transformed PMSetup XML element to the PMLogEntry with the corresponding time stamp.

        :param File file_object: PM counter file object
        """
        for _, pm_setup_unconverted in ET.iterparse(
                file_object,
                remove_blank_text=True,
                tag="PMSetup"):
            time_stamp = self._get_time_stamp(pm_setup_unconverted)
            interval = self._get_interval(pm_setup_unconverted)
            if self._interval and interval not in self._interval:
                continue
            self._add_pm_setup_to_log_entry(time_stamp, pm_setup_unconverted)

    def _add_pm_setup_to_log_entry(self, time_stamp, pm_setup_unconverted):
        if time_stamp not in self.__pm_log_entries:
            self.__pm_log_entries[time_stamp] = PMLogEntry(
                pm_setup=PMSetup(
                    pm_xml=ET.Element("PMSetup")),
                timestamp=time_stamp)
        pm_setup_converted = self.__pm_log_entries[time_stamp].pm_setup.pm_xml
        self._convert_pm_setup(pm_setup_unconverted, pm_setup_converted)

    @staticmethod
    def _convert_pm_setup(pm_setup_unconverted, pm_setup_converted):
        for pm_mo_result in pm_setup_unconverted:
            dn = "/".join(
                (elem.text for elem in pm_mo_result.findall("MO/DN")))
            current_parent = pm_setup_converted
            for mo_component in dn.split("/"):
                mo_class, mo_id = mo_component.split("-", 1)
                found_element = current_parent.find(
                    "%s[@id='%s']" % (mo_class, mo_id))
                if found_element is None:
                    current_parent = ET.SubElement(
                        current_parent,
                        mo_class,
                        attrib={'id': mo_id})
                else:
                    current_parent = found_element
            pm_target = pm_mo_result.xpath("*[self::PMTarget or self::NE-WBTS_1.0]")[0]
            ET.SubElement(
                current_parent,
                pm_target.get("measurementType"),
                attrib={pi.tag: pi.text for pi in pm_target})

    def _get_time_stamp(self, pm_setup):
        start_time = pm_setup.get("startTime")
        if start_time.count(":") == 4:
            start_time = start_time[:start_time.rindex(":")]
        time_stamp = parse(start_time)
        return time_stamp

    def _get_interval(self, pm_setup):
        return int(pm_setup.get("interval"))

    def __iter__(self):
        """
        Iterate through PM log entries.

        :return: yield a PMLogEntry
        """
        for file_obj in self._file_obj_iterator:
            with file_obj as file_obj:
                self._parse_pm_file(file_obj)
        for pm_log_entry in sorted(self.__pm_log_entries.values(), key=lambda pm_log_entry: pm_log_entry.timestamp):
            yield pm_log_entry
